from pathlib import Path

MAIN = Path('app/src/main/java/com/whisper/wowreader/MainActivity.java')
READER = Path('app/src/main/java/com/whisper/wowreader/BookReaderActivity.java')
GRADLE = Path('app/build.gradle')


def replace_once(text, old, new, label):
    if old not in text:
        raise SystemExit(f'missing anchor: {label}')
    return text.replace(old, new, 1)

# ---- Responsive library: calculate columns from usable card width, not device breakpoints. ----
main = MAIN.read_text(encoding='utf-8')
old_layout = '''    private void configureLibraryLayout() {\n        if (libraryRecycler == null) return;\n        int widthDp = Math.round(getResources().getDisplayMetrics().widthPixels /\n                Math.max(1f, getResources().getDisplayMetrics().density));\n        if (!gridMode) libraryColumns = 1;\n        else if (widthDp >= 900) libraryColumns = 5;\n        else if (widthDp >= 680) libraryColumns = 4;\n        else if (widthDp >= 430) libraryColumns = 3;\n        else libraryColumns = 2;\n\n        GridLayoutManager layout = new GridLayoutManager(this, libraryColumns);\n        layout.setSpanSizeLookup(new GridLayoutManager.SpanSizeLookup() {\n            @Override public int getSpanSize(int position) {\n                if (position <= 1) return libraryColumns;\n                if (visibleBooks.isEmpty() && position == 2) return libraryColumns;\n                return 1;\n            }\n        });\n        libraryRecycler.setLayoutManager(layout);\n    }\n\n    private int libraryCardWidth() {\n        int screen = getResources().getDisplayMetrics().widthPixels;\n        int gap = dp(12);\n        int side = dp(14);\n        int columns = Math.max(1, libraryColumns);\n        return Math.max(dp(118), (screen - side * 2 - gap * (columns - 1)) / columns);\n    }'''
new_layout = '''    private int calculateLibraryColumns(int widthPx) {\n        if (!gridMode) return 1;\n        float density = Math.max(1f, getResources().getDisplayMetrics().density);\n        float widthDp = Math.max(1f, widthPx / density);\n        // Keep covers at a comfortable book-like size while using all available space.\n        // This naturally produces 2 columns on phones and 3–6 on tablets/foldables/landscape.\n        final float sideDp = 28f;\n        final float gapDp = 12f;\n        final float minCardDp = 154f;\n        float usable = Math.max(minCardDp, widthDp - sideDp);\n        int columns = (int) Math.floor((usable + gapDp) / (minCardDp + gapDp));\n        return Math.max(2, Math.min(6, columns));\n    }\n\n    private void configureLibraryLayout() {\n        if (libraryRecycler == null) return;\n        int width = libraryRecycler.getWidth() > 0\n                ? libraryRecycler.getWidth() : getResources().getDisplayMetrics().widthPixels;\n        libraryColumns = calculateLibraryColumns(width);\n\n        GridLayoutManager layout = new GridLayoutManager(this, libraryColumns);\n        layout.setSpanSizeLookup(new GridLayoutManager.SpanSizeLookup() {\n            @Override public int getSpanSize(int position) {\n                if (position <= 1) return libraryColumns;\n                if (visibleBooks.isEmpty() && position == 2) return libraryColumns;\n                return 1;\n            }\n        });\n        libraryRecycler.setLayoutManager(layout);\n    }\n\n    private void updateLibraryColumnsForWidth(int widthPx) {\n        if (libraryRecycler == null || widthPx <= 0) return;\n        int wanted = calculateLibraryColumns(widthPx);\n        if (wanted == libraryColumns) return;\n        libraryColumns = wanted;\n        GridLayoutManager layout = new GridLayoutManager(this, libraryColumns);\n        layout.setSpanSizeLookup(new GridLayoutManager.SpanSizeLookup() {\n            @Override public int getSpanSize(int position) {\n                if (position <= 1) return libraryColumns;\n                if (visibleBooks.isEmpty() && position == 2) return libraryColumns;\n                return 1;\n            }\n        });\n        libraryRecycler.setLayoutManager(layout);\n        if (libraryAdapter != null) libraryAdapter.notifyDataSetChanged();\n    }\n\n    private int libraryCardWidth() {\n        int screen = libraryRecycler != null && libraryRecycler.getWidth() > 0\n                ? libraryRecycler.getWidth() : getResources().getDisplayMetrics().widthPixels;\n        int gap = dp(12);\n        int side = dp(14);\n        int columns = Math.max(1, libraryColumns);\n        return Math.max(dp(118), (screen - side * 2 - gap * (columns - 1)) / columns);\n    }'''
main = replace_once(main, old_layout, new_layout, 'responsive library layout')

old_adapter = '''        libraryRecycler.setAdapter(libraryAdapter);\n        root.addView(libraryRecycler, new FrameLayout.LayoutParams(\n                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));'''
new_adapter = '''        libraryRecycler.setAdapter(libraryAdapter);\n        libraryRecycler.addOnLayoutChangeListener((v, left, top, right, bottom,\n                                                   oldLeft, oldTop, oldRight, oldBottom) -> {\n            int width = right - left;\n            if (width > 0 && width != oldRight - oldLeft)\n                libraryRecycler.post(() -> updateLibraryColumnsForWidth(width));\n        });\n        root.addView(libraryRecycler, new FrameLayout.LayoutParams(\n                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT));'''
main = replace_once(main, old_adapter, new_adapter, 'dynamic width listener')
MAIN.write_text(main, encoding='utf-8')

# ---- True edge-to-edge immersive reader. ----
reader = READER.read_text(encoding='utf-8')

old_set_content = '''        setContentView(root);\n        updateChromeTheme();\n        updateAnnotationButton();\n        hideControls();\n        enterImmersive();'''
new_set_content = '''        installReaderSafeAreaHandling();\n        setContentView(root);\n        updateChromeTheme();\n        updateAnnotationButton();\n        hideControls();\n        enterImmersive();'''
reader = replace_once(reader, old_set_content, new_set_content, 'reader safe-area install')

old_immersive = '''    private void enterImmersive() {\n        getWindow().getDecorView().setSystemUiVisibility(\n                View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY |\n                View.SYSTEM_UI_FLAG_LAYOUT_STABLE |\n                View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION |\n                View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN |\n                View.SYSTEM_UI_FLAG_HIDE_NAVIGATION |\n                View.SYSTEM_UI_FLAG_FULLSCREEN);\n    }'''
new_immersive = '''    private void installReaderSafeAreaHandling() {\n        if (root == null) return;\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {\n            WindowManager.LayoutParams attrs = getWindow().getAttributes();\n            attrs.layoutInDisplayCutoutMode =\n                    WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES;\n            getWindow().setAttributes(attrs);\n\n            root.setOnApplyWindowInsetsListener((v, insets) -> {\n                android.view.DisplayCutout cutout = insets.getDisplayCutout();\n                int safeTop = cutout == null ? 0 : cutout.getSafeInsetTop();\n                int safeBottom = cutout == null ? 0 : cutout.getSafeInsetBottom();\n                if (topBar != null) {\n                    FrameLayout.LayoutParams p = (FrameLayout.LayoutParams) topBar.getLayoutParams();\n                    int wanted = safeTop + dp(8);\n                    if (p.topMargin != wanted) { p.topMargin = wanted; topBar.setLayoutParams(p); }\n                }\n                if (bottomBar != null) {\n                    FrameLayout.LayoutParams p = (FrameLayout.LayoutParams) bottomBar.getLayoutParams();\n                    int wanted = safeBottom + dp(12);\n                    if (p.bottomMargin != wanted) { p.bottomMargin = wanted; bottomBar.setLayoutParams(p); }\n                }\n                return insets;\n            });\n        }\n    }\n\n    @Override\n    protected void onResume() {\n        super.onResume();\n        View decor = getWindow().getDecorView();\n        decor.postDelayed(this::enterImmersive, 80L);\n    }\n\n    @Override\n    public void onWindowFocusChanged(boolean hasFocus) {\n        super.onWindowFocusChanged(hasFocus);\n        if (hasFocus) getWindow().getDecorView().postDelayed(this::enterImmersive, 55L);\n    }\n\n    private void enterImmersive() {\n        Window window = getWindow();\n        View decor = window.getDecorView();\n\n        window.addFlags(WindowManager.LayoutParams.FLAG_DRAWS_SYSTEM_BAR_BACKGROUNDS);\n        window.setStatusBarColor(Color.TRANSPARENT);\n        window.setNavigationBarColor(Color.TRANSPARENT);\n\n        // Keep the content laid out edge-to-edge on every supported Android version.\n        decor.setSystemUiVisibility(\n                View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY |\n                View.SYSTEM_UI_FLAG_LAYOUT_STABLE |\n                View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION |\n                View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN |\n                View.SYSTEM_UI_FLAG_HIDE_NAVIGATION |\n                View.SYSTEM_UI_FLAG_FULLSCREEN);\n\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {\n            window.setStatusBarContrastEnforced(false);\n            window.setNavigationBarContrastEnforced(false);\n        }\n        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {\n            window.setDecorFitsSystemWindows(false);\n            android.view.WindowInsetsController controller = window.getInsetsController();\n            if (controller != null) {\n                controller.setSystemBarsBehavior(\n                        android.view.WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);\n                controller.hide(android.view.WindowInsets.Type.statusBars() |\n                        android.view.WindowInsets.Type.navigationBars());\n            }\n        }\n    }'''
reader = replace_once(reader, old_immersive, new_immersive, 'true immersive mode')
READER.write_text(reader, encoding='utf-8')

# Version bump.
gradle = GRADLE.read_text(encoding='utf-8')
gradle = replace_once(gradle, 'versionCode 20', 'versionCode 21', 'version code')
gradle = replace_once(gradle, "versionName '2.8.0'", "versionName '2.9.0'", 'version name')
GRADLE.write_text(gradle, encoding='utf-8')

print('WoW Reader v2.9 migration applied')
